def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    mark = {(r, c) for r in range(h) for c in range(w) if g[r][c] == 9}
    r0, r1 = min(r for r, c in mark), max(r for r, c in mark)
    c0, c1 = min(c for r, c in mark), max(c for r, c in mark)

    # Find the L corner: intersection of its full-length arms.
    corner = None
    for r in (r0, r1):
        for c in (c0, c1):
            if all((r, x) in mark for x in range(c0, c1 + 1)) and \
               all((x, c) in mark for x in range(r0, r1 + 1)):
                corner = (r, c)
                break
        if corner:
            break
    cr, cc = corner
    arm_r = 1 if r1 > cr else -1
    arm_c = 1 if c1 > cc else -1
    open_r, open_c = -arm_r, -arm_c

    # Recolor the 7 object(s) situated in the open quadrant.
    for r in range(h):
        for c in range(w):
            if g[r][c] == 7 and (r - cr) * open_r > 0 and (c - cc) * open_c > 0:
                g[r][c] = 9
    return g
